def try_decrypt_with_key_length(ciphertext_hex, key_hex, length):
    ciphertext = unhexlify(ciphertext_hex)
    key = unhexlify(key_hex)[:length]  # Take only first 'length' bytes

    plaintext = bytearray()
    for i in range(len(ciphertext)):
        plaintext.append(ciphertext[i] ^ key[i % length])

    try:
        result = plaintext.decode('utf-8')
